fn naval(k:i32)->bool{matches!(k,39..=45)}
struct Board{sz:usize,n:usize,p:i32,turn:i32,stars:f64,tiles:Vec<Tile>,units:Vec<Option<Unit>>,cities:Vec<City>,tech:[bool;128],adj:Vec<Vec<usize>>,dist:Vec<i32>,home:Vec<usize>,own:Vec<usize>,enemy:Vec<usize>,citymap:Vec<Option<usize>>,income:f64,near_enemy:Vec<i32>,enemy_reach:Vec<Vec<usize>>,goals:Vec<(usize,f64,i32)>}
