 if !st.dash&&!u.attacked&&st.r>1{let mut setup:f64=-1e9;for &e in &b.enemy{if b.d(dst,e)<=st.r{let v=b.attack_value(u,b.units[e].unwrap(),dst);setup=setup.max(v);}}if setup>0.{score=score.max(0.8+setup*0.55-risk*0.55);}}
 if st.dash&&!u.attacked{let mut hitbest:f64=-1e9;for &e in &b.enemy{if b.d(dst,e)<=st.r{let v=b.attack_value(u,b.units[e].unwrap(),dst);hitbest=hitbest.max(v);}}if hitbest>0.{score=score.max(1.5+hitbest*0.98-risk*0.1);}}
 if u.attacked&&st.escape{score+=oldrisk*0.85;}
 if t.st==8&&t.owner==b.p&&!naval(u.k){score+=if b.tech[13]||b.tech[44]{3.}else{-2.};}
 if naval(u.k)&&t.ter>2{if u.k==45{score+=2.}else if u.k!=43&&b.enemy.len()>0{score-=4.;}}
 if b.tiles[a.s].st==1&&b.tiles[a.s].owner!=b.p{score-=200.;}if b.tiles[a.s].st==2&&!u.attacked&&!u.moved{score-=120.}
 if b.tiles[a.s].st==1&&b.tiles[a.s].owner==b.p{score+=1.8;if b.near_enemy[a.s]<=2&&b.danger(u,a.s,n)<u.hp{score-=4.;}}
 if matches!(u.k,8|41)&&!u.attacked{let firing=b.enemy.iter().any(|&e|b.d(a.s,e)<=st.r);if firing{score-=8.;}let min=b.enemy.iter().map(|&e|b.d(dst,e)).min().unwrap_or(99);if min<=2{score-=6.;}}
 if matches!(u.k,5)&&b.near_enemy[a.s]<=3&&b.tiles[a.s].st==1{score-=10.;}
